<!-- wp:group {"className":"tt-sec tt-isec","layout":{"type":"default"},"align":"full"} -->
<div class="wp-block-group alignfull tt-sec tt-isec"><!-- wp:group {"className":"tt-wrap","layout":{"type":"default"}} -->
<div class="wp-block-group tt-wrap"><!-- wp:group {"className":"tt-brows sp-stagger","layout":{"type":"default"}} -->
<div class="wp-block-group tt-brows sp-stagger"><!-- wp:group {"className":"tt-brow sp-reveal sp-reveal--up","layout":{"type":"default"}} -->
<div class="wp-block-group tt-brow sp-reveal sp-reveal--up"><!-- wp:heading {"level":2,"className":"tt-brow__h"} -->
<h2 class="wp-block-heading tt-brow__h">Our foundation and milestones</h2>
<!-- /wp:heading -->

<!-- wp:group {"className":"tt-brow__b","layout":{"type":"default"}} -->
<div class="wp-block-group tt-brow__b"><!-- wp:paragraph -->
<p>Mara Lindqvist founded Tabidachi Study Tours in 2009 after eleven years working as a geography teacher and leading her own Year nine field trips. Having experienced the pressures of school travel administration firsthand, she created an organisation where every school is supported by one dedicated planner from initial brief to final debrief.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>In 2009, we operated our first trip with one coach of forty-six students. We launched our first study tour abroad in 2012, introduced our dedicated twenty-four-hour duty line in 2015, began language weeks with host families in 2019, and completed our six hundred and twelfth trip in 2026.</p>
<!-- /wp:paragraph --></div>
<!-- /wp:group --></div>
<!-- /wp:group --></div>
<!-- /wp:group --></div>
<!-- /wp:group --></div>
<!-- /wp:group -->

<!-- wp:group {"className":"tt-sec tt-isec","layout":{"type":"default"},"align":"full"} -->
<div class="wp-block-group alignfull tt-sec tt-isec"><!-- wp:group {"className":"tt-wrap","layout":{"type":"default"}} -->
<div class="wp-block-group tt-wrap"><!-- wp:heading {"level":2,"className":"tt-h2 tt-isec__h"} -->
<h2 class="wp-block-heading tt-h2 tt-isec__h">People</h2>
<!-- /wp:heading -->

<!-- wp:paragraph {"className":"tt-ilede tt-ilede--sm"} -->
<p class="tt-ilede tt-ilede--sm">Our Ashby Vale team brings together former educators and travel logistics specialists. Mara Lindqvist directs the company as founder, having guided operations since 2009. Daniel Okafor joined in 2011 as head of tour leaders, overseeing staff training and on-the-road standards. Tomás Ibarra has managed operations, coaches, and flights since 2013. Sofia Ferreira joined in 2014 to lead school partnerships and trip planning. Ana Kowalska has overseen safety and risk assessments since 2015. Priya Shah joined in 2017 to manage parent liaison, while Elias Brandt joined in 2019 to coordinate curriculum workshops.</p>
<!-- /wp:paragraph -->

<!-- wp:html -->
<ul class="tt-people"><li class="tt-person"><span class="tt-person__n">Mara Lindqvist</span><span class="tt-person__r">Founder and director</span><span class="tt-person__s">since 2009</span></li><li class="tt-person"><span class="tt-person__n">Daniel Okafor</span><span class="tt-person__r">Head of tour leaders</span><span class="tt-person__s">since 2011</span></li><li class="tt-person"><span class="tt-person__n">Tomas Ibarra</span><span class="tt-person__r">Operations, coaches and flights</span><span class="tt-person__s">since 2013</span></li><li class="tt-person"><span class="tt-person__n">Sofia Ferreira</span><span class="tt-person__r">School partnerships</span><span class="tt-person__s">since 2014</span></li><li class="tt-person"><span class="tt-person__n">Ana Kowalska</span><span class="tt-person__r">Safety and risk assessments</span><span class="tt-person__s">since 2015</span></li><li class="tt-person"><span class="tt-person__n">Priya Shah</span><span class="tt-person__r">Parent liaison</span><span class="tt-person__s">since 2017</span></li><li class="tt-person"><span class="tt-person__n">Elias Brandt</span><span class="tt-person__r">Curriculum workshops</span><span class="tt-person__s">since 2019</span></li></ul>
